template:
feature cloud-note version "1.0.0"
command cloud-note permission "aetherscript.example.cloud" sender any {
  let message = "Welcome to the clouds."
  let stars = 2 + 1
  if stars >= 3 {
    send message
  } else {
    send "Keep exploring."
  }
}

mapSetExample.source:
feature palette version "1.0.0"
command palette permission "aetherscript.example.palette" sender any {
  let counts = {"red": 2}
  send text(unwrap(get(counts, "red")))
}
